import {S,P,T,D,C,U,B,refs} from './model.mjs';
export default [
S('Качество, сопровождение, интеграции и развитие','Проверки и улучшения опираются на исходный сценарий',P(['Качество','Ожидаемое поведение и подготовленные проверки'],['Сопровождение','Производительность, наблюдение и разбор сбоя'],['Развитие','Аналитика, уведомления и прототип поиска']),
'На четвёртом вебинаре рассмотрим, как проверяют ресурс, исследуют сбои и выбирают полезное развитие. Продолжим путь заявки Анны. Подготовим примеры проверок, разберём производительность и потерянный ответ. Затем добавим уведомление и рассмотрим прототип поиска по интересам.',
'Все числовые результаты и журналы далее условные. Ожидаемый результат проверки будем отличать от фактически наблюдённого. Аудитория ничего не выполняет: весь материал представлен готовыми разборами.','Введение короче основного разбора.'),
S('Качество в пользовательском сценарии','Полезный результат требует согласованности всех частей',P(['Правильные данные','Одна заявка Анны относится к проекту 17'],['Правильный доступ','Её видят Анна и Ирина в пределах своих прав'],['Понятный результат','Подача и решение имеют точные подписи'],['Устойчивый путь','Сбой обмена не создаёт ложного вывода']),
'Качество ресурса оценивают относительно потребностей и условий использования. Для нашего пути недостаточно красивой формы. Нужны правильная запись, доступ по ролям и понятный результат. Если заявка сохранилась дважды, нарушено правило учёта. Если она видна чужому преподавателю, нарушены полномочия. Если интерфейс объявил отказ без сведений о сохранении, нарушена точность обратной связи. Эти примеры показывают разные стороны одной пользовательской задачи.',
'Мы начинаем проверку с согласованных требований, а не с произвольного поиска необычных действий. Затем рассматриваем границы и отказы. Полнота зависит от того, какие риски существенны для проекта. Нельзя доказать отсутствие всех возможных ошибок несколькими красивыми снимками. Но можно подготовить проверяемые условия, зарегистрировать фактический результат и адресно исправить несоответствие. Следующий слайд покажет эту связь на ФТ-01.','Не сводите качество только к внешнему виду.'),
S('Требование и ожидаемое поведение','ФТ-01 задаёт основание проверки',T(['Часть проверки','Подготовленное описание'],[['Основание','ФТ-01: сохранение и показ своей заявки'],['Предусловия','Анна вошла, проект открыт, пары ещё нет'],['Действие','Подать допустимую мотивацию'],['Ожидание','Одна заявка pending видна в своих обращениях'],['Фактический результат','Заполняется при выполнении на реализации']]),
'Проверка должна опираться на известное правило. Для ФТ-01 устанавливаем исходные условия: действующий вход Анны, открытый проект и отсутствие её заявки. Затем выполняется подача с допустимым текстом. Ожидаем однажды созданную запись pending и её видимость в своём разделе. Последняя строка таблицы намеренно не заполнена вымышленным успехом. Фактический результат получают только при выполнении на конкретной реализации и версии.',
'Если прежняя заявка уже существует, исходное условие нарушено и мы проверяем другой случай. Если текст короткий, проверяется ограничение длины. Поэтому одинаковая кнопка не означает одинаковую проверку. Подготовленные условия делают вывод воспроизводимым: другой человек понимает, что именно делали и почему ожидали такой результат. Дальше различим типы несоответствий, чтобы связать их с последствиями и приоритетом.','Прочитайте предусловия до действия.'),
S('Виды дефектов','Несоответствие проявляется в данных, доступе или представлении',T(['Дефект','Наблюдаемое поведение','Нарушенное решение'],[['Повторная запись','У Анны две заявки на проект 17','Уникальность пары'],['Неправильный доступ','Чужой преподаватель меняет статус','Принадлежность проекта'],['Ложное сообщение','После обрыва заявлено «не сохранена»','Неопределённость результата'],['Неверная подпись','accepted показан как «Отклонена»','Словарь статусов']]),
'Дефект — несоответствие ожидаемому свойству или поведению. Он может находиться в программе, данных или проектном решении. На экране четыре разные ситуации. Повтор нарушает учёт, доступ чужого преподавателя — правило полномочий, ложное сообщение — точность интерфейса, неправильный перевод — согласованность представления. Для каждого случая можно указать основание и наблюдение. Так замечание становится пригодным для исправления.',
'Описание «всё работает неправильно» не помогает найти причину. Полезнее указать версию, исходные условия, действие и результат. При этом наблюдаемый дефект не всегда сразу раскрывает внутреннюю причину. Две заявки могут появиться из-за отсутствия ограничения или из-за другого пути записи. Сначала фиксируем достоверное поведение, затем исследуем механизм. Это различие пригодится и в разборе инцидента, где симптом не совпадает с причиной.','Отделяйте наблюдаемый результат от предполагаемой причины.'),
S('Приоритет исправления','Важность определяется последствиями и условиями возникновения',T(['Ситуация','Последствие','Учебный приоритет'],[['Чужой преподаватель меняет решение','Нарушены права и результаты участия','Высокий'],['Повторная заявка','Искажён учёт участников','Высокий'],['Неудачный перенос длинного заголовка','Часть текста труднее прочитать','Зависит от доступности действия'],['Небольшое различие отступа','Сценарий остаётся доступным','Ниже при равных условиях']]),
'Приоритет определяет порядок работы над исправлением. Он зависит от ущерба, распространённости и условий. Нарушение прав может быть важнее небольшого визуального расхождения. Но внешняя проблема тоже станет существенной, если скрывает кнопку для целой группы пользователей. Поэтому нельзя оценивать важность только по категории «интерфейс» или «сервер». Нужно связать дефект с возможностью выполнить задачу и с последствиями неправильного результата.',
'В таблице приведена учебная оценка при указанных условиях. Она не является универсальным регламентом для любого проекта. Команда согласует собственный порядок и учитывает доступность обходного пути. Если мотивация теряется при ошибке, человек может повторить ввод, но это всё равно ухудшает путь. Приоритет не отменяет необходимость описать и исправить подтверждённое несоответствие. Теперь перейдём к видам подготовленных проверок.','Назовите приоритет учебной оценкой, а не общим стандартом.'),
S('Позитивная проверка','Допустимые условия приводят к ожидаемому успеху',T(['Условия','Действие','Ожидание'],[['Студент 12, проект 17 открыт, пары нет','Подать допустимую мотивацию','201; одна запись pending'],['Ирина 7, свой проект, заявка pending','Сохранить accepted','200; статус accepted'],['Анна вошла, заявка существует','Открыть свои заявки','Видна 104 без чужих записей']]),
'Позитивная проверка рассматривает действие при допустимых условиях. Она показывает, что полезный основной путь поддержан. В первом случае создаётся одна заявка. Во втором Ирина сохраняет решение по своему проекту. В третьем Анна получает собственный список. Для каждой проверки исходный набор подготавливают отдельно. Если выполнить создание повторно без возврата к нужным условиям, результат закономерно изменится на конфликт.',
'Ожидаемый успех нужно читать полностью. Код 201 без правильной записи недостаточен. Наличие записи без видимого результата не завершает ФТ-01. Поэтому проверка охватывает и данные, и представление в нужных пределах. Таблица является подготовленным набором ожиданий, а не утверждением, что работающий сервис прошёл все случаи. Фактическое выполнение и его сведения оформляются отдельно. На следующем шаге посмотрим на отказ как ожидаемое правильное поведение.','Не называйте позитивной любую проверку, которая завершилась без ошибки.',[refs.testing]),
S('Негативная проверка','Корректный отказ тоже является правильной работой',T(['Условия','Действие','Ожидание'],[['Мотивация 49 символов','Попытка создать заявку','422; новой записи нет'],['Пара 12 и 17 занята','Повторная подача','409 APPLICATION_EXISTS'],['Проект закрыт','Новая подача','409 PROJECT_CLOSED'],['Анна установлена как student','Попытка решения','403; статус прежний']]),
'Негативная проверка использует недопустимое условие и ожидает предусмотренный отказ. Если короткая мотивация не сохранилась, это правильный результат. Если студент не смог принять собственную заявку, система выполнила правило. Поэтому слово «негативная» не означает плохое качество проверки. Оно относится к условиям действия. Важно также убедиться, что отказ не оставил недопустимую запись или случайное изменение.',
'Текст ошибки должен соответствовать причине. При закрытом проекте просьба увеличить мотивацию была бы неверной даже при отсутствии новой заявки. При повторе полезно направить к существующему обращению. Ожидаемый отказ включает несколько наблюдаемых признаков: код, содержание и сохранность состояния. Эти элементы помогают проверить связность договора и интерфейса. Дальше рассмотрим значения около границы, где особенно легко ошибиться на единицу.','Подчеркните, что предусмотренный отказ — успех проверки.',[refs.testing]),
S('Граничные значения мотивации','Проверяем обе стороны каждой включённой границы',T(['Длина после нормализации','Ожидание по правилу длины'],[['49','Отказ'],['50','Допустима'],['51','Допустима'],['999','Допустима'],['1000','Допустима'],['1001','Отказ']]),
'Граничная проверка исследует значения на краю диапазона и рядом с ним. Для нашей мотивации минимум пятьдесят, максимум тысяча, оба включены. Поэтому сорок девять и тысяча один отклоняются, а точные границы допустимы. Такое соседство помогает обнаружить ошибку сравнения: больше вместо больше или равно, меньше вместо меньше или равно. Мы не повторяем сотни произвольных длин, если цель — проверить именно эти условия.',
'Для полного успешного создания остальные предусловия также должны быть выполнены. В каждой независимой проверке берём открытый проект и отсутствие предыдущей пары. Строки состоят из обычной буквы «а» заданное число раз, чтобы не смешивать границу с неоднозначностью сложных символов. Нормализация выполняется до подсчёта. Это готовые тестовые данные преподавателя, а не задание слушателям генерировать строки самостоятельно.','Не утверждайте, что допустимость длины отменяет остальные правила.',[refs.testing]),
S('Модульная проверка','Небольшое правило исследуют отдельно от всего пути',P(['Вход функции','Нормализованный текст заданной длины'],['Изолированное правило','Попадает ли длина в 50–1000'],['Ожидаемый результат','Да на границе, нет за границей']),
'Модульная проверка рассматривает небольшой элемент программы отдельно. Для нашего примера это может быть функция допустимости мотивации. Ей передают подготовленный текст и сравнивают результат с ожиданием. Не требуется открывать браузер или настоящий проект, если задача ограничена правилом длины. Такое исследование помогает быстро найти ошибку в локальном условии. Однако оно не доказывает, что форма передаёт правильный текст или обработчик использует эту функцию.',
'Граница проверки должна быть ясна. Если функция считает длину до нормализации, а договор — после, отдельная корректность сравнения ещё не означает правильность всего поведения. Можно проверять эти шаги вместе или отдельно, но их связь надо сохранить. Далее интеграционная проверка исследует взаимодействие частей, а сквозная — весь пользовательский путь. Разные уровни дополняют друг друга и не заменяются одним названием.','Модуль — ограниченная часть программы, не отдельная тема лекции.',[refs.testing]),
S('Интеграционная проверка','Взаимодействие обработчика и базы поддерживает правило',P(['Обработчик','Получает установленного студента и допустимые данные'],['База','Сохраняет заявку и удерживает уникальную пару'],['Результат','Первая запись появляется, повтор даёт согласованный отказ']),
'Интеграционная проверка исследует взаимодействие частей. В нашем примере важно, как обработчик сохраняет данные и как понимает ограничение базы. Даже если функция длины исправна, неверная обработка уникальности может вернуть непонятный технический сбой. Подготовленный случай создаёт одну допустимую запись, затем проверяет повтор при соответствующих исходных условиях. Цель — увидеть согласованность границы между логикой и хранением.',
'Это ещё не обязательно полный браузерный путь. Можно обращаться к операции напрямую в подготовленной среде. Нужно зафиксировать, какие зависимости настоящие, а какие заменены моделью. Если вместо базы используется упрощённая имитация без ограничения, нельзя считать проверенной реальную уникальность хранения. Поэтому отчёт должен точно описывать охват. На следующем слайде расширим наблюдение до интерфейса и действий обоих участников.','Уточните, какие части взаимодействуют в конкретной проверке.',[refs.testing]),
S('Сквозной сценарий','Полезный путь наблюдают через все основные части',P(['Анна','Выбирает проект, вводит мотивацию и получает подтверждение'],['Система','Сохраняет одну заявку и выдаёт нужные представления'],['Ирина','Открывает свой проект и принимает решение'],['Анна снова','Видит сохранённый итог в своих заявках']),
'Сквозная проверка проходит основной путь через интерфейс, обработку и данные. В нашем случае Анна подаёт заявку, Ирина принимает решение, Анна видит итог. Она помогает обнаружить разрывы между исправными по отдельности частями. Например, сервер может сохранять accepted, а экран показывать неверную подпись. Или форма может отправлять другой project_id. Такие ошибки не обязательно проявятся в изолированной функции длины.',
'Подготовка сквозного сценария требует управляемых данных и разных пользовательских контекстов. Нельзя незаметно использовать полномочия преподавателя во время студенческого шага. Также основной успех не заменяет проверки отказов и границ. Мы рассматриваем уровни как разные способы получить свидетельства о системе. Для курса показан готовый маршрут и ожидаемые результаты, а не заявлено фактическое прохождение работающим приложением.','Последовательно смените точку зрения Анны и Ирины.',[refs.testing]),
S('Проверка прав доступа','Запрет подтверждается неизменностью данных',T(['Исполнитель','Попытка','Ожидание'],[['Анна, student','PATCH собственной заявки на accepted','403; pending сохраняется'],['Другой преподаватель','PATCH заявки проекта 17','403; статус прежний'],['Ирина, teacher 7','Решение по своему проекту из pending','Допустимо при остальных условиях']]),
'Проверка доступа должна включать запрещённые действия, а не только отсутствие кнопок. Подготовленная попытка Анны обратиться к операции решения должна закончиться отказом. Затем убеждаются, что статус не изменился. Другой преподаватель тоже не получает право по одному знанию номера. Ирина проходит условие принадлежности, но ещё должна действовать из допустимого исходного состояния. Так роль и связь объекта проверяются отдельно.',
'Если интерфейс скрыл кнопку, а прямое обращение изменило запись, правило нарушено. Если сервер вернул отказ, но всё равно сохранил изменение, наблюдаемый код тоже не доказывает защиту. Поэтому ожидаемый результат включает состояние данных после попытки. В примере не нужен настоящий взлом или самостоятельный поиск обходов аудитории. Мы показываем готовое обращение и объясняем основание запрета по согласованной матрице.','Отказ и неизменность статуса проверяются вместе.'),
S('Проверка повторной подачи','Конкурирующие попытки оставляют одну запись',T(['Исходное состояние','Действия','Ожидаемое состояние'],[['Пары 12 и 17 нет','Одна допустимая подача','Одна запись'],['Пара уже существует','Повторная подача','Та же одна запись'],['Пары ещё нет','Две почти одновременные попытки','Не более одной записи; одна попытка конфликтует']]),
'Проверка повтора имеет несколько разных условий. Последовательный повтор проверяет реакцию на уже существующую запись. Одновременные попытки проверяют защиту от состязания между чтением и сохранением. Нельзя считать второй случай проверенным только отключением кнопки. Подготовленная схема должна показать обращения, результаты и итоговое число строк для пары. Успешность определяется согласованностью данных и понятным ответом, а не тем, какая вкладка оказалась первой.',
'В отчёте важно не заявлять больше выполненного. Если показали только последовательные обращения, конкуренция ещё не исследована. Наши таблицы содержат ожидаемое поведение и объясняют необходимую защиту. Фактический запуск потребовал бы управляемой среды и регистрации результатов. Такой подход удерживает границу между проектным разбором и доказательством исправности реальной версии. Следующий слайд покажет, зачем повторять связанные проверки после изменения.','Не приравнивайте двойной щелчок к полной проверке конкуренции.'),
S('Регрессионная проверка','Изменение не должно разрушить согласованное ранее поведение',T(['Изменение','Что проверяем дополнительно'],[['Новый текст сообщения','Правильная причина и сохранность поля'],['Оптимизация списка','Своих пользователей и корректные статусы'],['Расширение уведомления','Сохранение заявки при отказе внешней доставки'],['Прототип поиска','Обычный путь подачи остаётся согласованным']]),
'Регрессия — появление неправильного поведения после изменения того, что раньше работало ожидаемо. Регрессионная проверка направлена на сохранение существенных прежних свойств. Если оптимизировали список, важно не только время, но и правильный отбор. Если добавили уведомление, нельзя потерять регистрацию заявки при сбое доставки. Объём проверки выбирают по влиянию изменения и рискам, а не механическим повторением всех возможных действий.',
'Связи требований и решений помогают выбрать нужные случаи. Мы уже знаем, какие экраны и данные поддерживают ФТ-01, поэтому можем проследить влияние. Это не означает, что старый успешный протокол автоматически доказывает новую версию. В отчёте должна быть известна проверяемая редакция. Далее посмотрим, как оформлять результат так, чтобы ожидание, наблюдение и вывод не смешивались.','Регрессия — новое несоответствие после изменения.',[refs.testing]),
S('Ожидаемый и фактический результат','Учебный пример не выдаётся за проведённое испытание',T(['Поле отчёта','Готовый учебный пример'],[['Условия','Анна, открытый проект, пары нет, 49 символов'],['Ожидается','422; заявки нет; текст сохранён в форме'],['Фактически','Условный пример дефекта: получен 201'],['Вывод','При таком наблюдении нарушена нижняя граница'],['Статус примера','Не является результатом испытания действующего сервиса']]),
'На экране условный пример оформления дефекта. Мы заранее задаём ситуацию: вместо ожидаемого отказа короткий текст получил успешное создание. Это иллюстрация возможного несоответствия, а не журнал нашего работающего сервиса. В настоящем отчёте фактический результат берут из выполненной проверки и указывают версию. Затем сопоставляют с ожиданием. Такая структура позволяет другому человеку воспроизвести условия и понять вывод.',
'Если фактическая строка не заполнена, нельзя написать «проверка пройдена». Если наблюдение не соответствует предусловиям, вывод тоже потребует уточнения. Например, существующая заявка может дать конфликт раньше проверки длины. Поэтому важны управляемые исходные данные и точный предмет проверки. Мы завершили блок функционального качества и теперь перейдём к производительности, где такое же различие понадобится для условных измерений.','Прямо назовите фактическую строку условной иллюстрацией.'),
S('Медленная работа','Сначала определяют, какое действие и в каких условиях замедлено',P(['Симптом','Каталог долго появляется после открытия'],['Граница измерения','От начала запроса до получения нужных данных'],['Условия','Одинаковый набор, нагрузка и среда'],['Вывод','По ощущению ещё нельзя назвать узкое место']),
'Производительность связывают с конкретным действием и условиями. Фраза «сайт медленный» не определяет, что измерять. Для каталога можно наблюдать время запроса, для формы — путь до подтверждения. Нужно указать начало и конец, объём данных и нагрузку. Иначе два числа окажутся несопоставимыми. В учебном разборе все значения условные и используются для понимания причинной цепочки, а не как измерения нашего сайта.',
'Медленное появление списка не доказывает проблему базы. Задержка может находиться в сети, обработке или представлении. Сначала разделяют путь на участки, затем выбирают средство исследования. Оптимизация случайного места может не дать заметного эффекта. Следующие слайды покажут измерение, состав времени и несколько возможных решений с их ограничениями. Каждый раз будем сохранять связь с исходным пользовательским действием.','Не назначайте причину по одному ощущению пользователя.'),
S('Измерение времени','Число имеет смысл вместе с границами и единицами',T(['Параметр','Условие учебного сравнения'],[['Действие','Получение каталога'],['Набор','Одинаковые 1000 учебных проектов'],['Нагрузка','Одинаковое число одновременных обращений'],['Единица','Миллисекунды'],['Граница','Начало запроса — получение ответа'],['Статус чисел','Условная иллюстрация']]),
'Миллисекунда — тысячная доля секунды. Она удобна для небольших промежутков, но сама точность единицы не гарантирует качественное измерение. Нужно определить границы и условия. В таблице зафиксирован одинаковый объём каталога и одинаковая нагрузка. Если после изменения данных стало в десять раз меньше, ускорение нельзя полностью приписать новой программе. Если сеть изменилась, потребуется учитывать это различие.',
'Одного запуска может быть недостаточно, потому что время колеблется. В настоящем исследовании выбирают повторения и способ обобщения, сохраняя исходные сведения. Мы не добавляем случайные процентили без набора наблюдений. В учебных графиках показываем только обозначенную иллюстрацию. Такой аккуратный язык позволяет преподавателю объяснить метод, не выдавая придуманные числа за результаты испытания. Следующий слайд выделит сетевую часть пути.','Всегда произносите единицу рядом с числом.'),
S('Сетевая часть времени','Доставка и ожидание находятся вне самой команды базы',B([['Сеть и передача',180],['Серверная обработка',120],['Обращения к базе',700]],'мс','Условное разложение одного ответа: 180 + 120 + 700 = 1000 мс.'),
'На графике условный ответ занимает тысячу миллисекунд. Здесь для простоты выделены неперекрывающиеся части: передача, обработка и обращения к базе. Мы заранее определили такое разложение, поэтому значения можно сложить. В реальной параллельной обработке длительности участков могут перекрываться, и простая сумма не всегда допустима. На учебной схеме главное — увидеть относительный вклад и выбрать место дальнейшего исследования.',
'Сеть включает не только скорость канала, но и задержки обмена. Большой объём данных тоже может увеличить передачу. Однако самый крупный участок этой иллюстрации связан с базой. Это основание исследовать запросы, а не немедленно обещать конкретную оптимизацию. После изменения нужно повторить сравнение при тех же условиях и убедиться, что полезное содержимое ответа осталось правильным.','Подпишите условность и неперекрывающиеся части графика.'),
S('Обращения к базе','Количество и вид запросов влияют на работу списка',T(['Вариант','Что происходит','Следствие для исследования'],[['Один согласованный запрос','Получены нужные связанные сведения','Понятен единый план получения'],['Отдельный запрос для каждой строки','Число обращений растёт со списком','Проверить лишние повторные чтения'],['Получение всех полей','Переданы ненужные большие значения','Проверить состав ответа']]),
'Задержка базы может зависеть и от сложности команды, и от числа обращений. Если для каждой строки списка отдельно читать проект, число запросов растёт. Иногда полезнее получить нужные связанные сведения одним согласованным запросом. Но такой вывод нужно проверить на данных и плане. Мы не объявляем любое соединение автоматически быстрее любого другого способа. Важно исследовать фактическую структуру работы.',
'Также проверяют, не читаются ли ненужные поля. Для краткой карточки может не требоваться полный мотивационный текст всех обращений. Сокращение данных должно сохранять необходимое содержание и право доступа. После оптимизации список по-прежнему должен относиться к текущему пользователю. Иначе скорость улучшится ценой неправильного результата. Далее рассмотрим индекс как средство поиска строк и отдельно его издержки.','Не обещайте ускорение без исследования конкретного запроса.'),
S('Индексы','Дополнительная структура может ускорить подходящий поиск',P(['Запрос','Получить заявки конкретного студента'],['Индекс','Помогает находить строки по выбранному признаку'],['Цена','Занимает место и обновляется при изменениях'],['Проверка','План и время оценивают на подходящих данных']),
'Индекс — дополнительная структура, которая может помочь базе быстрее находить нужные строки. Для списка Анны существенен поиск по student_id. Но наличие индекса не означает ускорение любого запроса. База выбирает способ выполнения с учётом условий и данных. Если таблица мала или выбирается большая доля строк, другой путь может быть выгоднее. Поэтому решение связывают с конкретным запросом и проверяют.',
'Индекс занимает место и требует работы при изменениях. Добавлять его на каждое поле без причины не следует. Для уникальной пары уже существует соответствующая защита, но её пригодность для других выборок тоже требует понимания порядка столбцов и плана. В курсе достаточно показать назначение, цену и необходимость измерения. Мы не выполняем настройку настоящей базы в эфире. Следующий шаг рассмотрит объём передаваемого представления.','Не приравнивайте индекс к гарантированному ускорению.',[refs.index,refs.explain]),
S('Объём ответа','Передают необходимые сведения без потери пользовательского смысла',T(['Экран','Необходимое содержимое','Что можно не включать'],[['Каталог','Название, краткое описание, набор','Мотивации студентов'],['Свои заявки','Проект, статус, дата','Чужие обращения'],['Просмотр преподавателя','Мотивация выбранной заявки','Полные тексты всех соседних заявок']]),
'Объём передаваемых данных влияет на время и ресурсы. Сначала выясняют, что нужно конкретному экрану. Каталог не требует мотиваций студентов. Краткий список не обязан содержать полные тексты всех обращений, если они открываются отдельно. Такое сокращение должно сохранять согласованный смысл. Нельзя убрать статус из своих заявок только ради меньшего ответа: без него Анна не достигнет цели. Оптимизация подчиняется задаче.',
'Также важно учитывать число записей. При большом каталоге может потребоваться разделение выдачи на части, но это будет отдельное изменение договора. В текущий набор маршрутов мы не добавляем неописанные параметры как уже реализованную возможность. На слайде рассматривается принцип достаточности представления. Его можно проверить по связи экранов и полей: каждое передаваемое значение должно иметь назначение, а каждое необходимое значение — источник.','Не удаляйте обязательное содержание под видом ускорения.'),
S('Кеширование и актуальность','Сохранённая копия требует правила обновления',P(['Копия','Ранее полученное представление используется повторно'],['Польза','Меньше повторной работы при подходящих условиях'],['Риск','Сведения могут устареть'],['Пример','Проект закрыт после получения карточки']),
'Кеширование сохраняет результат для повторного использования. Оно может уменьшить задержки и нагрузку, если данные и правила допускают такую копию. Но у копии есть возраст. Карточка могла показать открытый набор, а проект затем закрыли. Поэтому наличие данных в браузере не заменяет актуальную проверку создания на сервере. Особенно внимательно рассматривают персональные списки: они связаны с пользователем и правами.',
'Не существует одного срока актуальности для всех ресурсов. Описание проекта и результат решения могут иметь разную допустимую задержку обновления. В нашем базовом договоре не вводим конкретный механизм кеша как обязательную часть. Мы объясняем возможный подход и его цену. Если его выбирают, нужно определить правила обновления и проверить, что чужие или устаревшие сведения не подставляются в неверный контекст.','Кеш — сохранённая копия результата с правилами использования.',[refs.cache]),
S('Сравнение оптимизации','Ускорение оценивают при одинаковых условиях и правильном результате',B([['До изменения',1000],['После изменения',400]],'мс','Условный пример при одинаковом наборе и нагрузке. Сокращение на 600 мс, то есть на 60 % от исходного времени.'),
'Условное время уменьшилось с тысячи до четырёхсот миллисекунд. Разница — шестьсот, то есть шестьдесят процентов исходного значения. Это не означает рост скорости на шестьдесят процентов в любом смысле: мы конкретно считаем уменьшение длительности относительно тысячи. Условия набора и нагрузки одинаковы. Одновременно проверяем правильность выдачи. Быстрый пустой список вместо нужных обращений не является успешной оптимизацией.',
'На настоящих измерениях понадобятся повторения и описание колебаний. Здесь два числа — учебная иллюстрация расчёта, а не проведённый эксперимент. Вывод ограничен заданным случаем. Мы не обещаем, что индекс или сокращение ответа всегда даст именно такое изменение. Дальше рассмотрим наблюдение за работающим приложением, где длительность становится одним из показателей наряду с ошибками и событиями отдельных запросов.','Произнесите знаменатель при расчёте процента.'),
S('Наблюдение за приложением','Разные сведения отвечают на разные вопросы о работе',T(['Вид сведений','Что помогает понять','Учебный пример'],[['Логи','Что произошло в конкретный момент','Сохранена заявка 104'],['Метрики','Как меняются числовые показатели','Количество ошибок за интервал'],['Трассировка','Как запрос прошёл через участки','Обработка, база, отправка ответа']]),
'Наблюдаемость связывают с возможностью понимать внутреннее состояние по доступным сведениям о работе. Для нашего разбора выделим логи, метрики и трассировку. Журнал содержит события, метрика — числовое обобщение, трассировка — путь конкретного обращения. Эти средства дополняют друг друга. График ошибок укажет период отклонения, но сам по себе не объяснит судьбу заявки Анны. Для этого понадобятся связанные события и состояние данных.',
'Мы используем определения для проектного понимания, не разворачивая обязательную платформу мониторинга. Пример может быть реализован разными средствами. Существенно заранее решить, какие события и идентификаторы помогут ответить на пользовательский вопрос. При этом нельзя записывать в журнал всё подряд: избыточные персональные тексты усложнят хранение и доступ. На следующих слайдах увидим компактный набор сведений для одного запроса.','Логи — журнал событий, метрики — числовые показатели.',[refs.telemetry]),
S('Логи','События связывают время, операцию и результат',C('Учебный журнал','10:00:00 req=r-104 action=create_application\n10:00:00 req=r-104 validation=ok\n10:00:01 req=r-104 saved application=104\n10:00:01 req=r-104 response_write=failed','Условные строки одного запроса. Мотивация и секреты сеанса не записаны.'),
'Лог — запись события, произошедшего в работе программы. В нашем подготовленном журнале видны начало создания, успешная проверка, сохранение заявки и проблема записи ответа. Все строки объединены номером запроса r-104. Это условное обозначение, выбранное для чтения, а не реальный технический журнал. Время также учебное. По этим сведениям можно сформировать гипотезу о разрыве после сохранения, а затем подтвердить состояние базы.',
'В журнал не включён полный мотивационный текст или секрет сеанса. Для разбора пути они не нужны. Полезность записи определяется вопросом сопровождения, а не максимальным объёмом. Также отдельная строка saved должна означать действительно подтверждённое сохранение, иначе журнал будет вводить в заблуждение. События проектируют с теми же требованиями к точности, что пользовательские сообщения.','Сначала укажите общий req, затем последовательность времени.',[refs.logs]),
S('Метрики','Числовой показатель имеет единицу и интервал',B([['10:00–10:05',0],['10:05–10:10',2],['10:10–10:15',8],['10:15–10:20',1]],'ошибок','Условные ошибки записи ответа за неперекрывающиеся пятиминутные интервалы. Ось категорий — интервалы времени.'),
'Метрика численно описывает свойство работы. На графике показано число ошибок записи ответа по пятиминутным интервалам. Это условные данные. Видно увеличение в одном периоде, но причина пока неизвестна. Для доли ошибок дополнительно понадобилось бы общее число соответствующих обращений. Восемь ошибок при десяти запросах и при миллионе имеют разный масштаб. Поэтому число без знаменателя и условий может вводить в заблуждение.',
'Метрика помогает обнаружить изменение и выбрать период исследования. Затем можно обратиться к журналам и отдельным запросам. Она не говорит автоматически, что все заявки потеряны: ошибка передачи ответа может возникнуть после сохранения. В нашем примере именно это различие важно. Подписанные интервалы и единицы позволяют корректно прочитать график и удержать вывод в пределах того, что действительно показано.','Не называйте число ошибок долей без общего количества.',[refs.metrics]),
S('Путь запроса','Трассировка показывает связанные участки выполнения',P(['Приём','Сервер получил обращение'],['Проверка','Установлены пользователь и условия'],['Данные','Сохранена заявка'],['Ответ','Предпринята передача результата браузеру']),
'Трассировка связывает участки работы одного обращения. Её элементы могут иметь начало, конец и контекст. Благодаря этому видно, где запрос провёл время и на каком участке возник отказ. В нашем учебном пути выделены приём, проверки, данные и ответ. Это упрощённое представление: фактическая система может иметь больше внутренних шагов. Мы выбираем те, которые помогают объяснить судьбу заявки без лишних подробностей.',
'Трассировка отличается от общего графика длительности. Она относится к конкретному обращению и связывает его части. Однако полнота зависит от того, что система действительно зарегистрировала и передала. Отсутствие участка не всегда означает, что действие не произошло. Поэтому свидетельства сопоставляют с журналом и данными. Следующий слайд уточнит назначение номера запроса, который помогает объединять такие сведения.','Трассировка — связанный путь одного обращения.',[refs.traces]),
S('Идентификатор запроса','Один номер помогает сопоставить связанные события',T(['Обозначение','Что идентифицирует','Учебное значение'],[['request_id','Попытку обработки обращения','r-104'],['application.id','Сохранённую заявку','104'],['student_id','Пользователя','12']]),
'Номер запроса и номер заявки имеют разные назначения. request_id объединяет сведения одной попытки обработки. application.id обозначает сохранённый объект. Повторная попытка может получить другой номер запроса, но столкнуться с уже существующей заявкой сто четыре. Поэтому одинаковая часть цифр в нашем учебном обозначении не означает один тип идентификатора. Мы выбрали читаемый пример, а не правило генерации номеров.',
'При обращении пользователя полезно найти конкретную попытку и затем связанный объект. Номер запроса не должен сам становиться правом доступа или содержать секретный сеанс. Его назначение — сопоставление событий. Если запрос не создал заявку из-за короткого текста, технический номер может существовать без application.id. Такое различие помогает не требовать номер сохранённой заявки в ситуации, где объект ещё не возник.','Разделите номер попытки и номер объекта.'),
S('Уведомление о сбое','Сигнал запускает проверку, а не устанавливает причину',P(['Условие','Показатель превысил согласованную границу'],['Сигнал','Сопровождение получает сведения о периоде и операции'],['Исследование','Сопоставляются метрики, журналы и состояние данных']),
'Сигнал мониторинга помогает заметить отклонение вовремя. Но он не доказывает причину. Увеличение ошибок ответа не означает, что база удаляет заявки. Полезный сигнал сообщает, какой показатель изменился, за какой период и где искать подробности. Границу выбирают по условиям эксплуатации, а не придумывают универсальное число для всех сервисов. В учебном случае мы показываем сам порядок реакции без настоящей рассылки.',
'Также важно не путать уведомление сопровождению со студенческим подтверждением или будущим уведомлением преподавателю о новой заявке. У этих сообщений разные получатели и цели. Сейчас речь о техническом отклонении. Следующий разбор покажет, как от симптома «Анна не увидела подтверждение» перейти к установленной последовательности событий и подходящему восстановлению. Никакой отправки реальным людям в демонстрации не требуется.','Сигнал — повод исследовать, не готовый диагноз.'),
S('Инцидент: ответ не дошёл','Заявка сохранена, браузер не получил подтверждение',P(['1. Анна отправила','Началась обработка допустимого запроса'],['2. Сервер сохранил','В базе существует заявка 104'],['3. Связь прервалась','Ответ не дошёл до браузера'],['4. Интерфейс сообщил','Результат пока не удалось подтвердить']),
'Инцидент — событие, которое нарушило нормальное предоставление результата. Разберём полностью подготовленный случай. Анна нажала кнопку. Сервер успешно сохранил заявку сто четыре. При передаче ответа связь прервалась. Браузер не знает итог и сообщает неопределённость. В журнале есть подтверждённое сохранение и отказ передачи. В базе есть нужная пара. Значит, причина отсутствия видимого успеха находится после записи, а не в потере мотивации.',
'Действие сопровождения начинается с сопоставления сведений. Нельзя сразу просить Анну подавать новую заявку и обещать, что старой нет. После восстановления связи приложение получает собственный список. Если там видна сто четыре, пользовательский результат можно восстановить без новой записи. Этот случай связывает три предыдущих занятия и показывает пользу точных сообщений на каждом уровне. Дальше проверим, что восстановление действительно завершено.','Указывайте четыре события по порядку, не меняя состояние заявки.'),
S('Проверка восстановления','Связь вернулась и пользователь видит правильную запись',T(['Что проверяем','Ожидаемый признак'],[['Доступность чтения','GET /api/my/applications получает ответ'],['Содержимое','Заявка 104 относится к Анне и проекту 17'],['Единственность','Для пары существует одна запись'],['Представление','На экране «На рассмотрении»'],['Граница вывода','Это не проверяет все остальные функции']]),
'Восстановление нельзя считать завершённым только потому, что пропал технический сигнал. Нужно проверить пользовательский путь. Анна получает свои заявки, видит правильный проект и начальное состояние. В данных одна запись для пары. При этом мы не делаем вывод об исправности всего сервиса из одного успешного чтения. Критерий восстановления связан с конкретным инцидентом и тем результатом, который был нарушен.',
'Если чтение вернуло ошибку, работа ещё не завершена. Если интерфейс показывает чужую заявку, связь восстановилась, но появился другой существенный дефект. Поэтому полезно различать доступность и правильность. Подготовленная таблица даёт ведущему конкретный порядок объяснения. Она не является отчётом о реальном устранении сбоя в этом учебном сайте. Дальше рассмотрим пользовательские показатели, которые помогают выбирать улучшения за пределами технической доступности.','Не объявляйте все функции исправными по одному успешному чтению.'),
S('Технические и пользовательские показатели','Доступность не равна полезному завершению задачи',T(['Показатель','Что отражает','Чего не объясняет'],[['Доля ошибок API','Технические отказы обмена','Почему человек не начал подачу'],['Время ответа','Длительность выбранной операции','Понятность условий проекта'],['Доля подавших после формы','Прохождение пользовательского шага','Причину ухода каждого человека']]),
'Технические показатели описывают работу компонентов, пользовательские — прохождение задач. Быстрый ответ не гарантирует, что Анна поняла форму. Большое число открытий каталога не доказывает полезность выбора. Поэтому улучшения связывают с несколькими видами свидетельств. На экране показаны границы каждого показателя. Они помогают задавать следующий вопрос, а не автоматически устанавливают причину поведения.',
'В нашем учебном примере далее используем условную воронку. Она относится к одной группе и периоду. Мы не собираем настоящие данные слушателей и не выдаём их действия в этой презентации за аналитику «Проектного навигатора». Чёткое определение события, пользователя и успешного результата необходимо до расчёта доли. Иначе красивое число может оказаться смесью нажатий, повторных посещений и разных групп.','Объясните, какой вопрос решает каждый показатель.'),
S('События аналитики','Значение события определяется наблюдаемым действием',T(['Событие','Когда учитывается'],[['Открыт каталог','Показано содержимое каталога'],['Открыта карточка проекта','Показана выбранная карточка'],['Открыта форма','Человек дошёл до формы выбранного проекта'],['Успешная подача','Сохранённая заявка подтверждена системой']]),
'Событие аналитики фиксирует определённое действие или результат. Его название должно иметь точный смысл. Нажатие кнопки и успешное сохранение — разные события. Для конечного шага воронки выбираем именно подтверждённую подачу. Если считать только щелчки, сетевые отказы и повторы исказят число завершений. Поэтому событие связывают с тем фактом, который мы хотим измерить. В примере это зарегистрированная заявка.',
'Также заранее определяют, какие технические повторы исключаются. Одно обновление страницы не обязательно означает нового заинтересованного человека. Мы не проектируем здесь весь инструмент сбора данных или новую таблицу базовой заявки. Аналитика вводится как отдельный слой развития и наблюдения. Для подготовленного расчёта достаточно согласованных определений, чтобы читатель понимал происхождение каждого числа. Следующий шаг уточнит единицу подсчёта пользователей.','Не приравнивайте нажатие «Подать» к успешному сохранению.'),
S('Уникальные пользователи','Повторные действия одного участника не увеличивают число людей',T(['Действия в периоде','Нажатия','Уникальные пользователи'],[['Анна открыла форму трижды','3','1'],['Анна и другой студент открыли форму','2','2'],['Анна повторила отправку существующей заявки','Ещё одна попытка','Не новый подавший пользователь']]),
'Уникальный пользователь учитывается один раз по выбранному правилу идентификации в пределах периода. Поэтому три открытия формы Анной дают три действия, но одного человека. Для учебной воронки используем именно людей, а не все события. Это позволяет оценить переход группы между этапами. При этом в реальной аналитике способ идентификации и ограничения должны быть описаны: например, разные устройства могут затруднить сопоставление без установленной учётной записи.',
'В нашем сценарии работаем с вошедшими пользователями одной группы и устойчивыми учебными идентификаторами. Повтор заявки не создаёт нового успешного участника. Но доля по пользователям всё ещё зависит от периода и правил порядка событий. На следующем слайде зададим их явно, чтобы числа можно было корректно сравнить. Это предотвращает незаметную смену знаменателя и смешение различных наборов людей.','Чётко произносите единицу «человек», а не «нажатие».'),
S('Период и группа измерения','Все этапы сравнивают в одном согласованном наборе',T(['Условие','Учебное решение'],[['Период','Одна условная учебная неделя'],['Группа','Одни и те же 100 вошедших студентов'],['Порядок','Следующий этап учитывается после предыдущего в периоде'],['Повторы','Один человек учитывается на этапе один раз'],['Статус данных','Подготовленные условные числа']]),
'Перед расчётом фиксируем период и группу. В примере это одна условная неделя и сто студентов, открывших каталог. Следующие этапы считаем среди той же исходной группы и в согласованном порядке. Если человек открыл карточку до выбранного периода, этот случай не подмешивается без специального правила. Повторные открытия на этапе не увеличивают число людей. Такие условия делают учебную воронку последовательной.',
'Это одно из возможных определений аналитического набора, а не универсальная настройка всех систем. Реальный проект должен выбрать правила под свой вопрос. Важно не менять их внутри одного сравнения. Если каталог считается по всем посетителям, а форма только по части вошедших, вывод о потерях будет искажён. Поэтому определения входят в описание графика вместе с числами, единицей и периодом. Теперь можно прочитать саму воронку.','Покажите, что исходная группа остаётся одной.'),
S('Учебная воронка','100 открыли каталог, 25 успешно подали заявку',B([['Открыли каталог',100],['Открыли карточку',60],['Открыли форму',40],['Успешно подали',25]],'человек','Условная учебная неделя, одна группа, уникальные пользователи на каждом этапе в согласованном порядке.'),
'На графике четыре этапа. Из ста открывших каталог шестьдесят дошли до карточки, сорок — до формы, двадцать пять — до подтверждённой подачи. Среди открывших форму доля завершения равна двадцати пяти, делённым на сорок: шестьдесят две с половиной процента. От исходного каталога это двадцать пять процентов. Оба числа верны при разных знаменателях, поэтому нужно всегда называть, какую долю мы считаем.',
'Разница между этапами показывает место для исследования, а не автоматически обнаруженный дефект. Человек мог выбрать другой путь, передумать или не найти подходящую тему. На этом слайде мы не устанавливаем причину. Мы читаем условные числа по заранее определённой группе. Следующий слайд объяснит, какие выводы из такой картины допустимы и что потребуется для выбора конкретного улучшения.','Вычисление: 25 / 40 = 62,5 %, затем назовите знаменатель.'),
S('Ограничения воронки','Разница чисел не устанавливает причину ухода',T(['Наблюдение','Возможные объяснения','Что исследовать'],[['40 открыли форму, 25 подали','Трудность ввода, изменение намерения, сбой','Сообщения и путь формы'],['100 открыли каталог, 60 карточку','Нет подходящей темы или неясны описания','Содержание и способ выбора'],['Изменение доли после выпуска','Версия, состав группы или внешние условия','Сопоставимость периодов']]),
'По одной воронке нельзя установить причину потерь. Она показывает участок, который нужно исследовать. Уход с формы может быть связан с инструкцией, техническим отказом или обычным изменением намерения. Поэтому нельзя сразу объявить поле мотивации виновником и убрать ограничение. Такое изменение нарушило бы согласованное правило без доказанной пользы. Сначала сопоставляют сведения и формируют проверяемую гипотезу.',
'Также изменение показателя после выпуска не доказывает причинность. Группа могла отличаться по интересам, а каталог — по содержанию. Для обоснованного сравнения сохраняют условия или явно учитывают различия. Учебная воронка помогает выбрать направление следующего разбора. Её сила в точном описании пути, а предел — в недостатке сведений о причинах. Далее покажем, как перейти от наблюдения к ограниченному проектному предложению.','Не утверждайте причину по одной разнице столбцов.'),
S('Выбор следующего улучшения','Предложение связывает наблюдение, гипотезу и проверку',P(['Наблюдение','Часть пользователей открывает форму без завершения'],['Гипотеза','Инструкция длины недостаточно заметна'],['Изменение','Сделать границы видимыми рядом с полем'],['Проверка','Оценить понимание и сопоставимое завершение, сохраняя остальные правила']),
'Подготовим ограниченное предложение. Мы наблюдаем недостижение конечного шага, предполагаем трудность с инструкцией и предлагаем сделать её заметнее. Это гипотеза, а не установленная причина. Изменение не затрагивает допустимую длину и не добавляет новую роль. Проверка должна показать, помогает ли решение понять условие и выполнить путь. Так аналитический сигнал связывается с конкретным проектированием.',
'Если данные не подтверждают гипотезу, решение пересматривают. Важно заранее определить, какой результат будет полезным свидетельством и какие побочные свойства сохраняются. Увеличение числа нажатий без роста подтверждённых подач не докажет успех. Следующий блок покажет другое расширение — внешнее уведомление преподавателю. Оно добавляет зависимость, поэтому его нужно проектировать с сохранением основного результата заявки.','Назовите гипотезу предположением, требующим проверки.'),
S('Внешняя интеграция','Новый сервис получает ограниченную обязанность после сохранения',D(['Приложение','База заявок','Сервис уведомлений','Ирина'],[['Приложение','База заявок','Сначала сохранить заявку'],['Приложение','Сервис уведомлений','Затем передать уведомление'],['Сервис уведомлений','Ирина','Доставка сообщения']]),
'Интеграция — взаимодействие с внешней системой для выполнения части задачи. Добавим уведомление Ирине о новой заявке. Это расширение четвёртого занятия, а не скрытая часть прежней базовой архитектуры. Главный результат остаётся в приложении: заявка сначала сохраняется. Только затем предпринимается доставка уведомления. Такая граница позволяет не потерять учёт, если внешний сервис недоступен.',
'На схеме внешний сервис отвечает за свою часть доставки. Наше приложение отвечает за сохранение и регистрацию результата попытки. Мы не добавляем автоматически очередь или отдельного робота повторов. В учебном варианте повторная отправка будет действием сопровождения. Все дополнительные элементы потребовали бы явного проектирования. Дальше разберём, какие сведения нужны уведомлению и что происходит при успехе и отказе.','Явно назовите уведомление расширением.'),
S('Уведомление о новой заявке','Сообщение помогает перейти к собственному проекту',T(['Элемент','Учебное содержание'],[['Получатель','Ирина, ответственная за проект 17'],['Событие','Сохранена новая заявка 104'],['Краткий текст','Поступила заявка на проект «Сайт студенческого клуба»'],['Переход','Обычное открытие проекта после входа'],['Граница','Ссылка не даёт право без серверной проверки']]),
'Уведомление сообщает о событии и помогает вернуться к приложению. Получатель определяется через проект: Ирина отвечает за семнадцать. Не требуется отправлять полный мотивационный текст по внешнему каналу, если достаточно краткой информации и перехода. В самом приложении по-прежнему проверяются вход и право. Знание ссылки из уведомления не даёт чужому человеку возможность прочитать обращения или принять решение.',
'Сообщение не является единственным местом учёта. Если оно задержалось, Ирина всё равно может открыть список своего проекта. Это важное свойство расширения: полезная задача остаётся выполнимой без отдельной доставки. На следующих слайдах проследим порядок вызова и отказ. Мы рассматриваем подготовленные варианты содержания, а не отправляем реальные письма или сообщения от имени пользователя.','Никакой реальной отправки в рамках разбора не выполняется.'),
S('Порядок интеграционного вызова','Сначала устойчивый основной результат, затем дополнительная доставка',P(['Проверить и сохранить','Основная заявка проходит прежний согласованный путь'],['Подтвердить фиксацию','Заявка 104 существует независимо от уведомления'],['Вызвать внешний сервис','Передать ограниченные сведения о событии'],['Зафиксировать исход','Успех или отказ доставки записан отдельно']),
'Порядок выбран явно. Сначала выполняются правила создания и сохранение. После подтверждённой фиксации приложение обращается к внешнему сервису. Исход доставки регистрируется отдельно от статуса заявки. Он не превращает pending в accepted или rejected. Такое разделение сохраняет словарь рассмотрения и не смешивает пользовательский объект с техническим событием. На схеме четыре шага одной операции расширения.',
'Если внешний вызов занимает много времени, он может задержать общий обмен. В учебном варианте его ожидание ограничивают, а созданную заявку не отменяют из-за отказа доставки. Более сложное асинхронное устройство потребовало бы очереди и отдельной обработки. Мы не вводим их молча. Это честная граница простого варианта: возможный сбой между сохранением и вызовом нужно видеть и восстанавливать средствами сопровождения. Дальше рассмотрим оба исхода внешней попытки.','Не добавляйте автоматическую очередь в базовую схему.'),
S('Успешная доставка','Успех внешней попытки не означает решение по заявке',T(['Результат','Что означает','Что остаётся прежним'],[['Заявка сохранена','Обращение существует','Статус pending'],['Сервис принял отправку','Успешен согласованный этап передачи','Ирина ещё могла не прочитать'],['Подтверждена доставка','Есть предусмотренное подтверждение канала','Решение преподавателя не принято']]),
'Слова «отправлено», «принято сервисом» и «доставлено» могут обозначать разные этапы. Нужно читать договор выбранного внешнего сервиса. В нашей подготовленной модели успешная доставка означает получение предусмотренного подтверждения. Она не доказывает, что Ирина прочитала сообщение или одобрила Анну. Статус заявки остаётся pending до отдельного решения в приложении. Это ещё один пример необходимости точного значения события.',
'Если поставщик подтверждает только приём к отправке, нельзя подписать такой результат как прочтение человеком. Проектировщик должен сохранить эту границу в журналах и интерфейсе сопровождения. Для лекции мы не выбираем конкретный канал. Показываем, какие вопросы нужно согласовать и какой вывод допустим из полученного подтверждения. Затем сравним успешный путь с недоступностью, где основная заявка продолжает существовать.','Различайте приём сервисом, доставку и прочтение.'),
S('Недоступность внешнего сервиса','Отказ доставки не отменяет сохранённую заявку',P(['Основной результат','Заявка 104 уже находится в базе'],['Внешний отказ','Попытка уведомления не завершилась успешно'],['Учет','Проблема доставки зарегистрирована отдельно'],['Доступ Ирины','Список собственного проекта остаётся обычным путём']),
'Предположим, сервис уведомлений не ответил. На момент вызова заявка уже сохранена. Поэтому приложение не удаляет её и не сообщает Анне, что подачи не было. Оно отдельно регистрирует недоставку. Ирина сможет увидеть обращение в обычном списке проекта. Такая граница снижает зависимость основного учёта от дополнительного канала. Но проблему доставки всё равно нужно исследовать и при необходимости повторить.',
'Временная неопределённость внешнего ответа может означать, что сообщение всё же дошло. Поэтому повторную отправку также нужно проектировать с пониманием возможных дубликатов уведомления. Это не то же самое, что дубликат заявки: разные объекты и последствия. В учебном варианте повтор выполняет сопровождение после проверки сведений. Мы не обещаем ровно одну доставку без механизма, который мог бы это обеспечить.','Сохраняйте различие заявки и уведомления.'),
S('Регистрация сбоя доставки','Техническое событие связано с существующей заявкой',C('Учебный журнал','application=104 saved=true\nnotification_attempt=n-1 result=timeout\napplication_status=pending\nrecovery=manual_review','Условные сведения. Отдельная попытка уведомления не добавляет статус к заявке.'),
'В журнале разделены факт сохранения, попытка уведомления и её исход. Номер n-1 относится к доставке, а сто четыре — к заявке. Состояние pending осталось прежним. Последняя строка обозначает принятый учебный порядок: ручной разбор сопровождением. Это не автоматическая команда повторов. Мы фиксируем сведения так, чтобы человек мог понять границу отказа и не искать потерю в неверном месте.',
'Сама регистрация требует пригодного места хранения и доступа для сопровождения. Если проблема нигде не зафиксирована, повтор будет зависеть от случайного сообщения. В простом варианте журнал и обычный список заявок помогают сопоставить события. Надёжное гарантированное восстановление при любых сбоях потребовало бы дополнительного проектирования. На следующем слайде покажем ограниченный, но понятный порядок ручного повторения без изменения основного объекта.','Не называйте строку recovery работающим автоматическим механизмом.'),
S('Повторная отправка','Сопровождение действует по проверенным сведениям',P(['Проверить','Заявка существует, предыдущая доставка не подтверждена'],['Уточнить исход','Если канал позволяет, проверить результат прежней попытки'],['Повторить','Выполнить отдельное действие доставки'],['Зафиксировать','Записать новый исход без новой заявки']),
'В учебном варианте повтор — отдельное действие сопровождения. Сначала убеждаются, что заявка существует и действительно требует уведомления. Затем по доступным сведениям уточняют прежний исход. Если ответа не было, возможна неопределённость доставки. Новая попытка не создаёт новую заявку и не меняет решение преподавателя. Её результат фиксируют отдельно, чтобы дальнейший разбор не начинался с той же неизвестности.',
'Ручной порядок не следует выдавать за автоматическую очередь. У него есть ограничения по скорости реакции и полноте контроля. Если объём вырос, может понадобиться устойчивое хранилище заданий и обработчик повторов. Тогда это расширит архитектуру и потребует собственных правил. Пока мы сохраняем простой вариант из исходного промпта. Следующий слайд свяжет обязанности приложения, внешнего сервиса и человека, выполняющего сопровождение.','Не создавайте вторую заявку при повторе уведомления.'),
S('Граница ответственности интеграции','Каждая часть подтверждает только свою работу',T(['Участник','Ответственность','Не следует обещать'],[['Приложение','Сохранить заявку, инициировать и учесть попытку','Прочтение Ириной'],['Внешний сервис','Выполнить оговорённый этап доставки','Правильность статуса заявки'],['Сопровождение','Разобрать отказ и управляемо повторить','Автоматическое восстановление без механизма'],['Ирина','Принять решение в своём проекте','Изменение результата через уведомление']]),
'Граница ответственности помогает не смешивать результаты. Приложение отвечает за заявку и свои действия обмена. Внешний сервис — за оговорённую доставку. Сопровождение — за разбор и повтор в выбранном простом варианте. Ирина принимает решение внутри приложения с обычной проверкой права. Ни одно подтверждение канала не должно автоматически одобрять обращение. Таблица закрепляет эти различия и показывает предел обещаний.',
'Мы завершили разбор интеграции без изменения основных сущностей и статусов. Дополнительные технические сведения относятся к доставке. Если проект позже требует автоматические повторы, их нужно добавить явно. Теперь перейдём к другому развитию — поиску по описанию интересов. Он будет помогать выбирать существующие проекты, сохраняя прежний механизм подачи. Такой переход покажет, как новые подходы соотносят с конкретной проблемой, а не добавляют ради модного названия.','Прочитайте ответственность вместе с пределом обещания.'),
S('Современные подходы','Новое средство оценивают по задаче и дополнительной ответственности',T(['Подход','Возможная польза','Что нужно проверить'],[['Управляемые сервисы','Меньше самостоятельных операций размещения','Зависимость и условия доступа'],['Компонентный интерфейс','Повторное использование согласованных элементов','Пригодность сценария'],['Интеллектуальный поиск','Поиск по смыслу интересов','Качество, ошибки и объяснимость']]),
'Современный подход полезен, когда решает установленную задачу. Управляемый сервис может уменьшить объём самостоятельной эксплуатации, но добавляет зависимость. Повторное использование компонентов помогает согласованности, но не выбирает за проектировщика нужный путь. Интеллектуальный поиск может сопоставить интерес с описаниями проектов, однако допускает ошибочные результаты. Поэтому выбор включает не только пользу, но и ответственность за ограничения.',
'Мы не составляем рейтинг продуктов и не утверждаем, что одно средство обязательно для веб-разработчика во всех случаях. Для нашего проекта выберем конкретную трудность: студент не знает формального названия подходящей темы. Тогда можно исследовать поиск по свободному описанию. Прежде чем обсуждать модель, нужно сформулировать гипотезу пользы, входные данные и проверяемый результат. Следующие слайды пройдут этот путь на готовом примере.','Не превращайте обзор в список обязательных технологий.'),
S('Выбор подхода по задаче','Сложность оправдывается наблюдаемой пользой',P(['Задача','Найти тему по собственному описанию интересов'],['Простой вариант','Понятные названия и обычный поиск по словам'],['Расширение','Поиск смысловой близости описаний'],['Критерий','Помогает выбрать существующий проект при приемлемых ошибках']),
'Сначала сравнивают более простое решение с предлагаемым расширением. Если названия проектов непонятны, редакционная правка может помочь лучше сложной модели. Если интерес описан другими словами, смысловой поиск может дать дополнительную пользу. Выбор зависит от каталога, запросов и условий. Мы не предполагаем заранее, что интеллектуальный вариант всегда победит. Это проверяемая гипотеза развития.',
'Для учебного прототипа цель ограничена: найти существующие проекты и объяснить соответствие. Он не принимает решение вместо преподавателя, не создаёт новые темы и не отменяет мотивацию. Такое ограничение делает результат обозримым. Также сохраняется обычный каталог, чтобы человек мог выбрать вручную. Далее рассмотрим конкретную проблему формулировки, которая может не совпасть с названием нужного проекта.','Сравните пользу с простым способом выбора.'),
S('Проблема поиска проектов','Интерес студента не всегда совпадает со словами каталога',T(['Описание интереса','Слова проекта','Возможная трудность'],[['Хочу делать сервисы для студенческих организаций','Сайт студенческого клуба','Не совпали основные формулировки'],['Хочу заниматься интерфейсами','Личный кабинет участника','Связь понятна по содержанию'],['Хочу работать с данными','Архив технических инструкций','Нужно уточнить реальную задачу']]),
'Студент может описать интерес иначе, чем автор назвал проект. Фраза о сервисах студенческих организаций по смыслу близка сайту клуба, хотя слова различаются. Иногда связь видна только в описании задач. Обычный поиск по точному слову может пропустить полезный вариант. Но смысловая близость тоже не гарантирует пригодность: похожее слово может иметь другое значение. Поэтому нужно изучать конкретные примеры запросов и результатов.',
'Эта проблема относится к выбору до подачи. Она не требует изменения статусов заявки. Если Анна нашла подходящий проект, дальше идёт по той же карточке и форме. Мы не включаем интерес как обязательное поле каждого пользователя в базовой модели. Он появляется только как новый вход расширенного поиска. Такой способ введения сохраняет ясность границы и помогает оценить реальный объём добавления.','Не добавляйте интересы в исходную таблицу users.'),
S('Гипотеза улучшения','Поиск по описанию поможет перейти к подходящей карточке',P(['Вход','Свободный текст о желаемой деятельности'],['Предположение','Смысловое сопоставление найдёт полезные темы'],['Выход','Существующие проекты с кратким объяснением'],['Проверка','Сравнить пригодность выбора с обычным каталогом']),
'Гипотеза формулируется как проверяемое предположение: описание интереса поможет найти подходящий существующий проект быстрее или понятнее. Нужно заранее определить, что считать пригодным результатом. В нашем примере оцениваем соответствие задачи и возможность перейти к обычной карточке. Мы не обещаем автоматическое зачисление или идеальное понимание намерения. Расширение оказывает помощь в выборе, а не заменяет все последующие действия.',
'Для проверки понадобятся заранее подготовленные запросы, каталог и критерии оценки. Нельзя оценивать только один удачный пример, выбранный после получения результата. Нужно включить неоднозначные и неподходящие случаи. Также полезно сравнить с обычным поиском, иначе невозможно понять добавленную пользу. На следующих слайдах покажем вход, упрощённую схему и два готовых результата — удачный и ошибочный.','Назовите гипотезу до изображения удачного результата.'),
S('Новые входные данные поиска','Запрос интереса относится к расширению',T(['Значение','Откуда появляется','Использование'],[['Текст интереса','Ввод студента','Сопоставление с каталогом'],['Описание проекта','Существующие проекты','Основа поиска'],['Идентификатор результата','Найденный существующий проект','Переход в обычную карточку'],['Мотивация заявки','По-прежнему вводится в форме','Не подменяется запросом поиска']]),
'Новое поле принимает описание интересов. Оно не является автоматически мотивацией заявки. Человек может искать несколько тем и менять запрос, а затем отдельно объяснить желание участвовать. Каталог предоставляет существующие названия и описания. Результат должен сохранять идентификатор реального проекта, чтобы переход не вёл к вымышленной карточке. Так новая функция использует базовые данные, но имеет собственный вход.',
'Текст интереса может содержать личные сведения, поэтому заранее определяют, нужно ли его сохранять и кому передавать. В учебном прототипе показываем только подготовленный запрос, без настоящей внешней отправки. Отдельный промышленный договор обработки потребовал бы своих решений. Для понимания достаточно видеть поток: описание интереса сопоставляется с описаниями существующих проектов, а выход связан с обычным каталогом. Далее изобразим это устройство.','Не объявляйте поиск работающей внешней моделью.'),
S('Схема интеллектуального поиска','Сопоставление выбирает из существующего каталога',D(['Текст интереса','Представление смысла','Сравнение с каталогом','Результаты с id проектов'],[['Текст интереса','Представление смысла','Преобразование для сравнения'],['Представление смысла','Сравнение с каталогом','Оценка близости описаний'],['Сравнение с каталогом','Результаты с id проектов','Выбор кандидатов']]),
'На схеме один из возможных подходов: текст преобразуется в представление для сравнения, затем сопоставляется с описаниями каталога. Выходом становятся кандидаты с реальными идентификаторами. Мы намеренно не привязываем прототип к конкретной модели и не называем оценку близости вероятностью правильного выбора. Близость помогает упорядочить результаты, но её смысл зависит от метода и данных. Это проектная схема, а не реализованный механизм нашего учебного сайта.',
'Важно сохранить каталог как источник допустимых объектов. Если пояснение формирует языковая модель, её текст нужно связывать с реальным содержанием проекта. Иначе красивое объяснение может приписать теме несуществующие задачи. На следующих экранах краткое соответствие будет опираться на интерфейсы и студенческие организации. Также покажем ошибку, чтобы ведущий мог объяснить пределы метода без обещания безошибочности.','Не называйте оценку близости вероятностью успеха.',[refs.ai]),
S('Экран прототипа поиска','Подготовленный результат ведёт в обычную карточку',U('Поиск проектов по интересам','default',{kind:'search',description:'Поле с запросом об интерфейсах и студенческих организациях; найден существующий проект 17; краткое объяснение и переход к карточке.'}),
'В поле готовый запрос: «Хочу заниматься интерфейсами и делать сервисы для студенческих организаций». Прототип показывает сайт студенческого клуба. Объяснение называет две опоры: интерфейсные задачи и студенческую организацию. Кнопка открывает обычную карточку проекта семнадцать. Подача пока не выполняется. Человек должен прочитать условия и затем заполнить привычную форму. Так расширение добавляет способ поиска, сохраняя основной путь.',
'Это подготовленный экран, а не фактически выполненный интеллектуальный запрос. На нём нет вымышленной точности девяносто девять процентов. Оценивать полезность будем отдельно на наборе случаев. Такой статус позволяет использовать прототип для обсуждения поведения, не утверждая наличие работающей модели. Дальше разберём, каким должно быть объяснение результата и почему оно не является доказательством правильности само по себе.','Прочитайте запрос, затем объяснение и переход.'),
S('Объяснение результата','Соответствие ссылается на содержание проекта',T(['Часть интереса','Содержание проекта 17','Обоснованное пояснение'],[['Интерфейсы','Личный кабинет участника','Есть задачи пользовательского интерфейса'],['Студенческие организации','Сайт студенческого клуба','Сервис относится к жизни клуба'],['Желание участвовать','Ещё не подтверждено формой','Поиск только помогает выбрать']]),
'Пояснение должно быть связано с действительным описанием проекта. Для интереса к интерфейсам опорой служит личный кабинет. Для студенческих организаций — сайт клуба. Мы не добавляем обещание работы с технологией, которой нет в карточке. Такое объяснение помогает человеку оценить пригодность результата. Но понятная фраза не доказывает, что алгоритм нашёл лучший вариант или правильно понял все ограничения.',
'Полезно дать возможность перейти к исходному описанию и проверить его самостоятельно. Если объяснение противоречит карточке, доверять нужно не гладкости формулировки, а уточнённым данным проекта. В учебном прототипе вывод ограничен конкретными совпадениями. Следующий пример покажет, как похожее слово может привести к неподходящей теме. Это подготовит обсуждение ошибок и проверки пользы без идеализации нового подхода.','Не приписывайте проекту отсутствующие технологии.'),
S('Ошибочная рекомендация','Похожее слово не гарантирует подходящую деятельность',U('Ошибочный результат поиска','wrong',{kind:'search',description:'На тот же запрос предложен архив инструкций; совпадение по слову «интерфейс» не подтверждает интерес к разработке интерфейсов.'}),
'На подготовленном ошибочном экране предложен архив технических инструкций. В описании встречается слово «интерфейс», но задачи могут относиться к систематизации документации, а не созданию пользовательских экранов. Словесное совпадение оказалось недостаточным. Это не реальный измеренный процент ошибок модели, а отдельный учебный случай. Он показывает, почему результаты нужно оценивать по содержанию и условиям, а не по знакомому слову.',
'Система должна оставлять обычный каталог и доступ к полному описанию. Человеку полезно понимать, что рекомендация — помощь, а не решение преподавателя. Если ошибок много, гипотеза пользы может не подтвердиться. Тогда нужно изменить данные, метод или отказаться от сложного варианта. Следующий слайд соберёт ограничения, которые должны сопровождать такой прототип до заявления о готовности к выпуску.','Называйте пример ошибочным и условным, без вымышленных измерений.'),
S('Ограничения прототипа','Помощь в выборе не заменяет проверку пригодности',P(['Каталог','В результате только существующие проекты'],['Качество','Возможны пропуски и неподходящие рекомендации'],['Объяснение','Проверяется по реальному описанию'],['Действие','Заявка подаётся через прежний согласованный механизм']),
'Ограничения нужно включать в проектное описание до выпуска. Результаты должны ссылаться на существующие проекты. Возможны как неподходящие предложения, так и пропуски хороших вариантов. Объяснение проверяется по содержанию. Человек сохраняет обычный путь выбора и подачи. Модель не получает право одобрять заявку, менять её статус или обещать участие. Эти границы удерживают расширение в понятном назначении.',
'Если используются внешние средства обработки текста, отдельно оценивают передачу данных, зависимость и условия эксплуатации. В учебном варианте такой вызов не реализован и не выполняется. Поэтому мы не заявляем промышленную готовность по одному экрану. Последний шаг разборa — подготовить критерии полезности, чтобы решение о развитии опиралось на сопоставимые примеры и наблюдения, а не только на привлекательный вид прототипа.','Сохраните обычный каталог как доступный вариант.',[refs.ai]),
S('Проверка полезности поиска','Удачные и ошибочные случаи оценивают по заранее заданным критериям',T(['Критерий','Подготовленная проверка'],[['Пригодность','Соответствует ли найденный проект описанному интересу'],['Достоверность','Существует ли проект и верно ли объяснение'],['Сравнение','Помогает ли подход относительно обычного каталога'],['Ошибки','Есть ли неоднозначные запросы и неподходящие результаты'],['Сохранность пути','Обычная подача и правила не изменены']]),
'Критерии определяют до оценки. Для набора запросов заранее описывают, какие проекты можно считать подходящими и почему. Включают не только очевидные совпадения, но и неоднозначные случаи. Затем сравнивают результаты и пользовательский путь с простым вариантом. Отдельно проверяют достоверность объяснения и сохранение основного механизма подачи. Одна удачная рекомендация не доказывает полезность на всём каталоге.',
'Фактическая оценка потребовала бы выполненных наблюдений. Вебинар предоставляет подготовленный план и два разобранных случая. Мы не выдумываем числовую точность или проведённое исследование. Если результаты неудовлетворительны, команда получает основание улучшить данные, уточнить задачу или выбрать более простое решение. Этим завершается разбор инновационного прототипа. В конце соберём условия выпуска и материалы сопровождения, связывая все четыре занятия.','Не подменяйте план проверки заявлением о её прохождении.'),
S('Готовность к выпуску','Нужны свидетельства о ключевом пути и известных ограничениях',T(['Область','Что должно быть известно'],[['Поведение','Проверены основная подача, права, повторы и границы'],['Среда','Доступны нужные компоненты и настройки'],['Данные','Подготовлены совместимость и восстановление'],['Расширения','Уведомления и поиск имеют явные границы'],['Вывод','Известны версия, результаты и нерешённые существенные проблемы']]),
'Готовность к выпуску — обоснованное решение по известным сведениям. Нужны результаты проверок конкретной версии, готовая среда и понятный порядок восстановления. Известные существенные проблемы нельзя скрыть общей надписью «готово». Расширения оцениваются вместе с их зависимостями. Если поиск только изображён в прототипе, он не становится реализованной функцией. Если уведомления имеют ручное восстановление, это должно быть известно сопровождению.',
'Мы не добавляем вымышленный промышленный акт приёмки. Таблица показывает состав сведений, на основании которых такое решение принимают в реальном проекте. Для учебного ресурса важна последовательность мысли: требование получает реализацию, проверку и условия эксплуатации. Осталось передать материалы тем, кто будет поддерживать приложение. Следующий слайд покажет заполненную по нашему примеру памятку без настоящих секретов и внешних контактов.','Не выдавайте учебный перечень за реальный протокол выпуска.'),
S('Памятка сопровождения','Сведения позволяют проверить состояние и выбрать следующий шаг',T(['Раздел','Учебное содержание'],[['Основной путь','Подача Анной, просмотр Ириной, итоговый статус'],['Диагностика','Версия, request_id, время, событие сохранения'],['Сбой ответа','Проверить свои заявки после восстановления связи'],['Сбой уведомления','Заявку сохранить, доставку разобрать и повторить отдельно'],['Восстановление','Учитывать совместимость схемы и новые записи']]),
'Памятка сопровождения связывает симптомы с доступными сведениями и действиями. Для нашего сервиса важно знать путь заявки, способ сопоставить запрос и запись, а также границу внешней доставки. При потерянном ответе проверяют сохранённое обращение. При отказе уведомления не создают новую заявку. При возврате версии учитывают данные. Эти сведения уже разобраны, поэтому памятка может быть краткой, но предметной.',
'В реальном документе понадобятся ответственные и проверенные адреса, однако у нас они не предоставлены. Мы не заполняем их вымышленными людьми. Учебная памятка показывает содержание и логику использования. Её ценность в том, что следующий участник понимает, какой факт установить первым и чего нельзя заключить из одного симптома. Последний слайд соединит всю цепочку проектных решений на примере заявки сто четыре.','Не добавляйте неподтверждённые контакты и адреса.'),
S('Полная цепочка проектных решений','Один результат связан с требованиями, экраном, данными и сопровождением',P(['Требование','Анна должна видеть зарегистрированное обращение'],['Проектирование','Форма, свои заявки и связанные сущности'],['Работа','POST, проверки, сохранение и подтверждённый ответ'],['Качество и развитие','Проверки, разбор сбоя, аналитика и ограниченные расширения']),
'Проследим итоговый пример. Потребность в подтверждении привела к ФТ-01. Для него спроектированы форма и свои заявки. Данные связывают студента двенадцать, проект семнадцать и заявку сто четыре. Сервер получает проект и мотивацию, определяет пользователя, проверяет правила и сохраняет одну запись. Анна видит pending, а после решения Ирины — один из итогов. Проверки исследуют допустимые и запрещённые ситуации.',
'Сопровождение различает потерю ответа и потерю записи. Аналитика помогает выбрать направление улучшения, но не устанавливает причину по одному числу. Уведомление вводится после сохранения, а поиск по интересам остаётся отдельным расширением выбора. Все эти решения имеют границы и источники. Так дисциплина «Проектирование информационных ресурсов» связывает анализ задачи с пригодным, понятным и поддерживаемым ресурсом для конкретных пользователей.','Завершите изложением связей, без опроса аудитории.')
];
